import { describe, it, expect } from 'vitest';
import { isKnownVoice } from '../../server/providers/kokoro.js';

// The voice id builds voices/<id>.bin; an unvalidated id would be a
// path-traversal / file-existence oracle, so only the closed preset set passes.
describe('kokoro isKnownVoice (path-traversal allowlist)', () => {
  it('accepts the preset voice ids', () => {
    for (const id of ['af_heart', 'af_bella', 'af_nicole', 'am_fenrir', 'am_michael', 'am_puck', 'bf_emma', 'bm_george', 'bm_fable']) {
      expect(isKnownVoice(id), id).toBe(true);
    }
  });

  it('rejects traversal payloads, prototype keys, unlisted upstream voices and unknown ids', () => {
    for (const id of [
      '../../../package',
      '../voices/af_heart',
      'af_heart/../../../etc/passwd',
      'af_heart.bin',
      '__proto__',
      'constructor',
      'toString',
      'hasOwnProperty',
      'af_sky', // an upstream voice that scripts/fetch-kokoro.mjs does not fetch
      'AF_HEART',
      '',
    ]) {
      expect(isKnownVoice(id), id).toBe(false);
    }
  });
});
import { describe, it, expect } from 'vitest';
import { synthesize, voices, available, DEFAULT_VOICE } from '../../server/providers/kokoro.js';

const ready = available();
if (!ready) {
  console.warn(
    '\n' +
      '┌──────────────────────────────────────────────────────────────────┐\n' +
      '│  ⚠️  KOKORO LIVE TEST SKIPPED: model assets not downloaded.         │\n' +
      '│  Run `npm run fetch:kokoro` (~333 MB) to enable on-device TTS.     │\n' +
      '└──────────────────────────────────────────────────────────────────┘\n',
  );
}

function looksLikeMp3(audio) {
  const id3 = audio.subarray(0, 3).toString('latin1') === 'ID3';
  const frameSync = audio[0] === 0xff && (audio[1] & 0xe0) === 0xe0;
  return id3 || frameSync;
}

// Duration of the provider's mp3 by walking its frame headers. Kokoro audio is
// 24 kHz mono, which lamejs writes as MPEG-2 Layer III: 576 samples a frame.
const MPEG2_L3_KBPS = [0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160];
const MPEG2_RATES = [22_050, 24_000, 16_000];
function mp3DurationMs(buf) {
  let frames = 0;
  let rate = 0;
  let i = 0;
  while (i + 4 <= buf.length) {
    // 11 sync bits, version 10 (MPEG-2), layer 01 (III); the CRC bit is free
    const isHeader = buf[i] === 0xff && (buf[i + 1] & 0xfe) === 0xf2;
    const kbps = MPEG2_L3_KBPS[buf[i + 2] >> 4];
