+    const text = 'one two three';
+    const words = spansToWords(text, [
+      span(0, 4, 10.4, 200.6),
+      span(4, 8, 200.6, 399.5),
+      span(8, 13, 399.5, 612.2),
+    ]);
+    expect(words.map((w) => [w.startMs, w.endMs])).toEqual([
+      [10, 201],
+      [201, 400],
+      [400, 612],
+    ]);
+  });
+
+  it('returns [] for empty input', () => {
+    expect(spansToWords('', [])).toEqual([]);
+  });
+});

